package com.hbm.client.wiaj.actors;
import com.mojang.blaze3d.vertex.*;import java.util.*;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;
final class JarRenderTypes extends RenderType {
 static final RenderType BEAM=create("hbm_wiaj_fel_beam",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.QUADS,4096,false,false,CompositeState.builder().setShaderState(RENDERTYPE_LIGHTNING_SHADER).setTransparencyState(LIGHTNING_TRANSPARENCY).setCullState(NO_CULL).createCompositeState(false));
 private JarRenderTypes(){super("unused",DefaultVertexFormat.PARTICLE,VertexFormat.Mode.QUADS,256,false,false,()->{},()->{});}
 private static final Map<ResourceLocation,RenderType> LIT=new HashMap<>(),GLOW=new HashMap<>();
 static RenderType flat(ResourceLocation texture){return LIT.computeIfAbsent(texture,id->create("hbm_wiaj_flat",DefaultVertexFormat.PARTICLE,VertexFormat.Mode.QUADS,4096,false,false,CompositeState.builder().setShaderState(new ShaderStateShard(GameRenderer::getParticleShader)).setTextureState(new TextureStateShard(id,false,false)).setLightmapState(LIGHTMAP).setCullState(NO_CULL).createCompositeState(false)));}
 static RenderType glow(ResourceLocation texture){return GLOW.computeIfAbsent(texture,id->create("hbm_wiaj_glow",DefaultVertexFormat.PARTICLE,VertexFormat.Mode.QUADS,4096,false,false,CompositeState.builder().setShaderState(new ShaderStateShard(GameRenderer::getParticleShader)).setTextureState(new TextureStateShard(id,false,false)).setLightmapState(LIGHTMAP).setTransparencyState(LIGHTNING_TRANSPARENCY).setWriteMaskState(COLOR_WRITE).setCullState(NO_CULL).createCompositeState(false)));}
 static VertexConsumer plain(VertexConsumer out){return new VertexConsumer(){public VertexConsumer addVertex(float x,float y,float z){out.addVertex(x,y,z);return this;}public VertexConsumer setColor(int r,int g,int b,int a){out.setColor(r,g,b,a);return this;}public VertexConsumer setUv(float u,float v){out.setUv(u,v);return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){out.setUv2(u,v);return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}};}
}
